def test_find_pets_by_status_success(headers, status):
    """
    Test finding pets by valid status values.

    Verifies the 200 response is returned when valid status is provided.
    """
    response = requests.get(
        url=f"{BASE_URL}{ENDPOINT}", 
        headers=headers, 
        params={"status": status}
    )
    assert response.status_code == 200
    assert response.headers["Content-Type"] == "application/json"
    
    # Validate schema of returned data
    for pet in response.json():
        assert "id" in pet and isinstance(pet["id"], int)
        assert "name" in pet and isinstance(pet["name"], str)
        assert "photoUrls" in pet and isinstance(pet["photoUrls"], list)
        if "tags" in pet:
            for tag in pet["tags"]:
                assert "id" in tag and isinstance(tag["id"], int)
                assert "name" in tag and isinstance(tag["name"], str)

